'use client';

import { Suspense, useState, useEffect, useCallback, useRef } from 'react';
import { useSearchParams, useRouter } from 'next/navigation';
import { Search, MapPin, Crosshair, AlertCircle, Map, List, X, Package } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { DashboardPageHeader } from '@/components/dashboard';
import { RadiusSelector } from '@/components/near-me/radius-selector';
import { FilterDrawer } from '@/components/near-me/filter-drawer';
import type { FilterState } from '@/components/near-me/filter-drawer';
import { SortDropdown } from '@/components/near-me/sort-dropdown';
import { EmptyState } from '@/components/ui/empty-state';
import { UnifiedProductCard } from '@/components/product/unified-product-card';
import { fromNearMeProduct } from '@/components/product/card-converters';
import { NearMeSkeleton } from '@/components/near-me/near-me-skeleton';
import { NearMeMap } from '@/components/near-me/near-me-map';
import { searchProducts, getRadiusBreakdown } from '@/lib/api/near-me';
import type { NearMeProduct, NearMeMeta } from '@/lib/api/near-me';

type SortOption = 'distance' | 'trust' | 'price_asc' | 'price_desc' | 'trending' | 'delivery';

const DEFAULT_CENTER = { lat: 19.076, lng: 72.8777 };

function NearMeContent() {
  const searchParams = useSearchParams();
  const router = useRouter();

  const [center, setCenter] = useState<{ lat: number; lng: number }>(DEFAULT_CENTER);
  const [radius, setRadius] = useState(25);
  const [sort, setSort] = useState<SortOption>('distance');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [products, setProducts] = useState<NearMeProduct[]>([]);
  const [meta, setMeta] = useState<NearMeMeta | null>(null);
  const [radiusCounts, setRadiusCounts] = useState<Record<number, number>>({});
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [geoStatus, setGeoStatus] = useState<'idle' | 'loading' | 'done' | 'error'>('idle');
  const [showMap, setShowMap] = useState(true);
  const [mapFullscreen, setMapFullscreen] = useState(false);
  const [mobileView, setMobileView] = useState<'map' | 'list'>('list');
  const loaderRef = useRef<HTMLDivElement>(null);

  const [filters, setFilters] = useState<FilterState>({
    minPrice: '',
    maxPrice: '',
    minTrustScore: '',
    verifiedOnly: false,
    tradgoOnly: false,
    maxMoq: '',
    deliveryTime: '',
  });

  useEffect(() => {
    const lat = searchParams.get('lat');
    const lng = searchParams.get('lng');
    const r = searchParams.get('radius');
    const s = searchParams.get('sort');
    if (lat && lng) {
      setCenter({ lat: parseFloat(lat), lng: parseFloat(lng) });
    }
    if (r) setRadius(parseInt(r, 10));
    if (s && ['distance', 'trust', 'price_asc', 'price_desc', 'trending', 'delivery'].includes(s)) {
      setSort(s as SortOption);
    }
  }, []);

  const syncUrl = useCallback((c: { lat: number; lng: number }, r: number, s: string) => {
    const params = new URLSearchParams();
    params.set('lat', c.lat.toFixed(4));
    params.set('lng', c.lng.toFixed(4));
    params.set('radius', r.toString());
    params.set('sort', s);
    router.replace(`/buyer/near-me?${params.toString()}`, { scroll: false });
  }, [router]);

  const fetchProducts = useCallback(async (pageNum: number, append: boolean) => {
    try {
      if (pageNum === 1) setLoading(true);
      else setLoadingMore(true);
      setError(null);

      const result = await searchProducts({
        lat: center.lat,
        lng: center.lng,
        radius,
        sort,
        page: pageNum,
        limit: 20,
        ...(filters.minPrice ? { minPrice: parseFloat(filters.minPrice) } : {}),
        ...(filters.maxPrice ? { maxPrice: parseFloat(filters.maxPrice) } : {}),
        ...(filters.minTrustScore ? { minTrustScore: parseInt(filters.minTrustScore, 10) } : {}),
        ...(filters.verifiedOnly ? { verifiedOnly: true } : {}),
        ...(filters.tradgoOnly ? { tradgoOnly: true } : {}),
        ...(filters.maxMoq ? { maxMoq: parseInt(filters.maxMoq, 10) } : {}),
        ...(filters.deliveryTime ? { deliveryTime: filters.deliveryTime } : {}),
      });

      if (append) {
        setProducts((prev) => [...prev, ...result.data]);
      } else {
        setProducts(result.data);
      }
      setMeta(result.meta);
    } catch (err: unknown) {
      const errObj = err as { response?: { data?: { message?: string } } };
      setError(errObj?.response?.data?.message || 'Failed to load products');
    } finally {
      setLoading(false);
      setLoadingMore(false);
    }
  }, [center.lat, center.lng, radius, sort, filters]);

  const fetchRadiusCounts = useCallback(async () => {
    try {
      const breakdown = await getRadiusBreakdown(center.lat, center.lng);
      const counts: Record<number, number> = {};
      breakdown.forEach((b) => { counts[b.radius] = b.count; });
      setRadiusCounts(counts);
    } catch { console.error('Failed to load radius counts'); }
  }, [center.lat, center.lng]);

  useEffect(() => {
    fetchProducts(1, false);
    fetchRadiusCounts();
    syncUrl(center, radius, sort);
  }, [center.lat, center.lng, radius, sort, filters]);

  useEffect(() => {
    if (page > 1) {
      fetchProducts(page, true);
    }
  }, [page]);

  useEffect(() => {
    setPage(1);
  }, [radius, sort, filters]);

  const detectLocation = () => {
    if (!navigator.geolocation) {
      setGeoStatus('error');
      return;
    }
    setGeoStatus('loading');
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const c = { lat: pos.coords.latitude, lng: pos.coords.longitude };
        setCenter(c);
        setGeoStatus('done');
      },
      () => {
        setGeoStatus('error');
      },
      { enableHighAccuracy: true, timeout: 10000 },
    );
  };

  const loadMore = useCallback(() => {
    if (!loadingMore && meta && page < meta.totalPages) {
      setPage((p) => p + 1);
    }
  }, [loadingMore, meta, page]);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) loadMore();
      },
      { threshold: 0.1 },
    );
    const el = loaderRef.current;
    if (el) observer.observe(el);
    return () => { if (el) observer.unobserve(el); };
  }, [loadMore]);

  const resetFilters = () => {
    setFilters({
      minPrice: '', maxPrice: '', minTrustScore: '',
      verifiedOnly: false, tradgoOnly: false, maxMoq: '', deliveryTime: '',
    });
  };

  const handleToggleFullscreen = () => {
    setMapFullscreen((prev) => !prev);
  };

  const handleCenterChange = useCallback((c: { lat: number; lng: number }) => {
    setCenter(c);
  }, []);

  return (
    <div className="space-y-4">
      <DashboardPageHeader
        title="Near Me"
        description="Discover products from suppliers around you"
      />

      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-text-tertiary" />
          <Input
            placeholder="Search products near you..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="h-10 pl-9"
          />
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <Button
            variant={geoStatus === 'done' ? 'accent' : 'outline'}
            size="sm"
            onClick={detectLocation}
            disabled={geoStatus === 'loading'}
          >
            <Crosshair className={`mr-1.5 h-4 w-4 ${geoStatus === 'loading' ? 'animate-spin' : ''}`} />
            {geoStatus === 'loading' ? 'Detecting...' : 'My Location'}
          </Button>
          <FilterDrawer filters={filters} onChange={setFilters} onReset={resetFilters} />
          <SortDropdown value={sort} onChange={setSort} />
          <div className="sm:hidden flex gap-1">
            <Button
              variant={mobileView === 'list' ? 'default' : 'outline'}
              size="sm"
              onClick={() => setMobileView('list')}
              aria-label="Show list view"
            >
              <List className="h-4 w-4" />
            </Button>
            <Button
              variant={mobileView === 'map' ? 'default' : 'outline'}
              size="sm"
              onClick={() => setMobileView('map')}
              aria-label="Show map view"
            >
              <Map className="h-4 w-4" />
            </Button>
          </div>
          <div className="hidden sm:flex">
            <Button
              variant={showMap ? 'default' : 'outline'}
              size="sm"
              onClick={() => setShowMap((prev) => !prev)}
              aria-label={showMap ? 'Hide map' : 'Show map'}
            >
              <Map className={`mr-1.5 h-4 w-4`} />
              {showMap ? 'Hide Map' : 'Show Map'}
            </Button>
          </div>
        </div>
      </div>

      <div className="sticky top-16 z-20 bg-surface-secondary dark:bg-dark-surface py-2">
        <RadiusSelector
          selected={radius}
          onChange={(r) => setRadius(r)}
          counts={radiusCounts}
        />
      </div>

      {error && (
        <div className="flex items-center gap-2 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:border-red-900/50 dark:bg-red-900/20 dark:text-red-400">
          <AlertCircle className="h-4 w-4 flex-shrink-0" />
          {error}
        </div>
      )}

      {/* Mobile: toggle between map and list */}
      <div className="sm:hidden">
        {mobileView === 'map' ? (
          <div className="h-[60vh] rounded-xl overflow-hidden">
            <NearMeMap
              center={center}
              radiusKm={radius}
              products={products}
              onLocateMe={detectLocation}
              geoStatus={geoStatus}
              geoLoading={geoStatus === 'loading'}
              isFullscreen={false}
              onToggleFullscreen={() => {}}
              onCenterChange={handleCenterChange}
            />
          </div>
        ) : (
          renderProductList({
            loading, products, meta, geoStatus, radius,
            loadingMore, loaderRef, page,
          })
        )}
      </div>

      {/* Desktop: split-screen layout */}
      <div className="hidden sm:flex gap-4">
        <div className={`${mapFullscreen ? 'w-0 hidden' : showMap ? 'w-1/2' : 'w-full'} transition-all duration-300`}>
          {renderProductList({
            loading, products, meta, geoStatus, radius,
            loadingMore, loaderRef, page,
          })}
        </div>
        {(showMap || mapFullscreen) && (
          <div className={`${mapFullscreen ? 'fixed inset-0 z-50 p-4 bg-surface-secondary dark:bg-dark-surface' : 'w-1/2'} transition-all duration-300`}>
            {mapFullscreen && (
              <div className="flex items-center justify-between mb-3">
                <h2 className="text-lg font-semibold text-text-primary dark:text-dark-text-primary">Map View</h2>
                <button
                  type="button"
                  onClick={() => setMapFullscreen(false)}
                  className="rounded-lg p-2 hover:bg-surface dark:hover:bg-dark-surface transition-colors"
                  aria-label="Close fullscreen map"
                >
                  <X className="h-5 w-5" />
                </button>
              </div>
            )}
            <div className={`rounded-xl overflow-hidden ${mapFullscreen ? 'h-[calc(100vh-8rem)]' : 'h-[calc(100vh-14rem)] sticky top-20'}`}>
              <NearMeMap
                center={center}
                radiusKm={radius}
                products={products}
                onLocateMe={detectLocation}
                geoStatus={geoStatus}
                geoLoading={geoStatus === 'loading'}
                isFullscreen={mapFullscreen}
                onToggleFullscreen={handleToggleFullscreen}
                onCenterChange={handleCenterChange}
              />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function renderProductList(opts: {
  loading: boolean;
  products: NearMeProduct[];
  meta: NearMeMeta | null;
  geoStatus: string;
  radius: number;
  loadingMore: boolean;
  loaderRef: React.RefObject<HTMLDivElement | null>;
  page: number;
}) {
  const { loading, products, meta, geoStatus, radius, loadingMore, loaderRef, page } = opts;

  if (loading) {
    return <NearMeSkeleton />;
  }

  if (products.length === 0) {
    return (
      <EmptyState icon={Package} title="No products found" description={geoStatus === 'error' ? 'Enable location access or enter a location manually.' : 'Try increasing the radius or adjusting filters.'} />
    );
  }

  return (
    <>
      <div className="text-sm text-text-tertiary dark:text-dark-text-tertiary mb-3">
        {meta && (
          <span>{meta.total} product{meta.total !== 1 ? 's' : ''} found within {radius} km</span>
        )}
      </div>
      <div className="space-y-3">
        {products.map((product) => (
          <UnifiedProductCard key={product.productId} product={fromNearMeProduct(product)} variant="compact" features={{ showLocation: true, showDelivery: true, showCompare: false, showWishlist: false }} />
        ))}
      </div>
      <div ref={loaderRef} className="py-4">
        {loadingMore && (
          <div className="flex items-center justify-center gap-2 text-sm text-text-tertiary">
            <div className="h-4 w-4 animate-spin rounded-full border-2 border-primary-600 border-t-transparent" />
            Loading more...
          </div>
        )}
        {meta && page >= meta.totalPages && products.length > 0 && (
          <p className="text-center text-xs text-text-tertiary">All products loaded</p>
        )}
      </div>
    </>
  );
}

export default function NearMePage() {
  return (
    <Suspense fallback={<div className="space-y-5"><DashboardPageHeader title="Near Me" description="Discover products from suppliers around you" /><NearMeSkeleton /></div>}>
      <NearMeContent />
    </Suspense>
  );
}
